// TypeScript Version: 4.1

/**
* Anchor position.
*/
type AnchorPosition = 'start' | 'middle' | 'end';

/**
* Vertical baseline.
*/
type VerticalBaseline = 'alphabetic' | 'top' | 'middle' | 'bottom' | 'line-top' | 'line-bottom';

/**
* Font style.
*/
type FontStyle = 'normal' | 'italic' | 'oblique';

/**
* Font weight.
*/
type FontWeight = 'normal' | 'bold' | 'lighter' | 'bolder' | '100' | '200' | '300' | '400' | '500' | '600' | '700' | '800' | '900' | number;

/**
* Anchor reference frame.
*/
type ReferenceFrame = 'bounds' | 'group';

/**
* Title orientation.
*/
type Orientation = 'left' | 'right' | 'top' | 'bottom';

/**
* Interface describing constructor options.
*/
interface Options {
	/**
	* Horizontal text alignment of the title and subtitle.
	*/
	align?: string;

	/**
	* Anchor position for placing the title and subtitle. Default: 'middle'.
	*/
	anchor?: AnchorPosition;

	/**
	* Angle (in degrees) of the title and subtitle text.
	*/
	angle?: number;

	/**
	* Boolean indicating whether ARIA attributes should be included in SVG output. Default: true.
	*/
	aria?: boolean;

	/**
	* Vertical baseline of the title and subtitle text.
	*/
	baseline?: VerticalBaseline;

	/**
	* Color of the title text.
	*/
	color?: string;

	/**
	* Horizontal offset (in pixels) added to the title and subtitle x-coordinate.
	*/
	dx?: number;

	/**
	* Vertical offset (in pixels) added to the title and subtitle y-coordinate.
	*/
	dy?: number;

	/**
	* Mark encodings for custom title styling.
	*/
	encode?: any;

	/**
	* Font name of the title text.
	*/
	font?: string;

	/**
	* Font size of the title text.
	*/
	fontSize?: number;

	/**
	* Font style of the title text.
	*/
	fontStyle?: FontStyle;

	/**
	* Font weight of the title text.
	*/
	fontWeight?: FontWeight;

	/**
	* Reference frame for the anchor position. Default: 'bounds'.
	*/
	frame?: ReferenceFrame;

	/**
	* Maximum allowed length (in pixels) of title and subtitle text.
	*/
	limit?: number;

	/**
	* Line height for multi-line title text.
	*/
	lineHeight?: number;

	/**
	* Orthogonal offset (in pixels) by which to displace the title from its position along the edge of the chart.
	*/
	offset?: number;

	/**
	* Title orientation. Default: 'top'.
	*/
	orient?: Orientation;

	/**
	* Subtitle text.
	*/
	subtitle?: string | Array<string>;

	/**
	* Color of the subtitle text.
	*/
	subtitleColor?: string;

	/**
	* Font name for the subtitle text.
	*/
	subtitleFont?: string;

	/**
	* Font size for the subtitle text.
	*/
	subtitleFontSize?: number;

	/**
	* Font style for the subtitle text.
	*/
	subtitleFontStyle?: string;

	/**
	* Font weight for the subtitle text.
	*/
	subtitleFontWeight?: string | number;

	/**
	* Line height for multi-line subtitle text.
	*/
	subtitleLineHeight?: number;

	/**
	* Padding (in pixels) between title and subtitle text.
	*/
	subtitlePadding?: number;

	/**
	* Title text. Default: [].
	*/
	text?: string | Array<string>;

	/**
	* Integer z-index indicating the layering of the title group relative to other axis, mark, and legend groups. Default: 0.
	*/
	zindex?: number;
}

/**
* Interface describing a JSON-serialized title instance.
*/
interface JSON {
	/**
	* Horizontal text alignment of the title and subtitle.
	*/
	align?: string;

	/**
	* Anchor position for placing the title and subtitle.
	*/
	anchor: AnchorPosition;

	/**
	* Angle (in degrees) of the title and subtitle text.
	*/
	angle?: number;

	/**
	* Boolean indicating whether ARIA attributes should be included in SVG output.
	*/
	aria: boolean;

	/**
	* Vertical baseline of the title and subtitle text.
	*/
	baseline?: VerticalBaseline;

	/**
	* Color of the title text.
	*/
	color?: string;

	/**
	* Horizontal offset (in pixels) added to the title and subtitle x-coordinate.
	*/
	dx?: number;

	/**
	* Vertical offset (in pixels) added to the title and subtitle y-coordinate.
	*/
	dy?: number;

	/**
	* Mark encodings for custom title styling.
	*/
	encode?: any;

	/**
	* Font name of the title text.
	*/
	font?: string;

	/**
	* Font size of the title text.
	*/
	fontSize?: number;

	/**
	* Font style of the title text.
	*/
	fontStyle?: FontStyle;

	/**
	* Font weight of the title text.
	*/
	fontWeight?: FontWeight;

	/**
	* Reference frame for the anchor position.
	*/
	frame: ReferenceFrame;

	/**
	* Maximum allowed length (in pixels) of title and subtitle text.
	*/
	limit?: number;

	/**
	* Line height for multi-line title text.
	*/
	lineHeight?: number;

	/**
	* Orthogonal offset (in pixels) by which to displace the title from its position along the edge of the chart.
	*/
	offset?: number;

	/**
	* Title orientation.
	*/
	orient: Orientation;

	/**
	* Subtitle text.
	*/
	subtitle?: Array<string>;

	/**
	* Color of the subtitle text.
	*/
	subtitleColor?: string;

	/**
	* Font name for the subtitle text.
	*/
	subtitleFont?: string;

	/**
	* Font size for the subtitle text.
	*/
	subtitleFontSize?: number;

	/**
	* Font style for the subtitle text.
	*/
	subtitleFontStyle?: string;

	/**
	* Font weight for the subtitle text.
	*/
	subtitleFontWeight?: string | number;

	/**
	* Line height for multi-line subtitle text.
	*/
	subtitleLineHeight?: number;

	/**
	* Padding (in pixels) between title and subtitle text.
	*/
	subtitlePadding?: number;

	/**
	* Title text.
	*/
	text: Array<string>;

	/**
	* Integer z-index indicating the layering of the title group relative to other axis, mark, and legend groups.
	*/
	zindex: number;
}

/**
* Interface describing a title instance.
*/
interface Title {
	/**
	* Horizontal text alignment of the title and subtitle.
	*
	* @example
	* var title = new Title();
	*
	* title.align = 'left';
	*
	* var v = title.align;
	* // returns 'left'
	*/
	align?: string;

	/**
	* Anchor position for placing the title and subtitle.
	*
	* @example
	* var title = new Title();
	*
	* title.anchor = 'start';
	*
	* var v = title.anchor;
	* // returns 'start'
	*/
	anchor: AnchorPosition;

	/**
	* Angle (in degrees) of the title and subtitle text.
	*
	* @example
	* var title = new Title();
	*
	* title.angle = 90;
	*
	* var v = title.angle;
	* // returns 90
	*/
	angle?: number;

	/**
	* Boolean indicating whether ARIA attributes should be included in SVG output.
	*
	* @example
	* var title = new Title();
	*
	* title.aria = false;
	*
	* var v = title.aria;
	* // returns false
	*/
	aria: boolean;

	/**
	* Vertical baseline of the title and subtitle text.
	*
	* @example
	* var title = new Title();
	*
	* title.baseline = 'top';
	*
	* var v = title.baseline;
	* // returns 'top'
	*/
	baseline?: VerticalBaseline;

	/**
	* Color of the title text.
	*
	* @example
	* var title = new Title();
	*
	* title.color = 'steelblue';
	*
	* var v = title.color;
	* // returns 'steelblue'
	*/
	color?: string;

	/**
	* Horizontal offset (in pixels) added to the title and subtitle x-coordinate.
	*
	* @example
	* var title = new Title();
	*
	* title.dx = 2;
	*
	* var v = title.dx;
	* // returns 2
	*/
	dx?: number;

	/**
	* Vertical offset (in pixels) added to the title and subtitle y-coordinate.
	*
	* @example
	* var title = new Title();
	*
	* title.dy = 2;
	*
	* var v = title.dy;
	* // returns 2
	*/
	dy?: number;

	/**
	* Mark encodings for custom title styling.
	*
	* @example
	* var title = new Title();
	*
	* title.encode = {
	*     'title': {
	*         'enter': {
	*             'fill': {
	*                 'value': 'steelblue'
	*             }
	*         }
	*     }
	* };
	*
	* var v = title.encode;
	* // returns {...}
	*/
	encode?: any;

	/**
	* Font name of the title text.
	*
	* @example
	* var title = new Title();
	*
	* title.font = 'Arial';
	*
	* var v = title.font;
	* // returns 'Arial'
	*/
	font?: string;

	/**
	* Font size of the title text.
	*
	* @example
	* var title = new Title();
	*
	* title.fontSize = 12;
	*
	* var v = title.fontSize;
	* // returns 12
	*/
	fontSize?: number;

	/**
	* Font style of the title text.
	*
	* @example
	* var title = new Title();
	*
	* title.fontStyle = 'italic';
	*
	* var v = title.fontStyle;
	* // returns 'italic'
	*/
	fontStyle?: FontStyle;

	/**
	* Font weight of the title text.
	*
	* @example
	* var title = new Title();
	*
	* title.fontWeight = 'bold';
	*
	* var v = title.fontWeight;
	* // returns 'bold'
	*/
	fontWeight?: FontWeight;

	/**
	* Reference frame for the anchor position.
	*
	* @example
	* var title = new Title();
	*
	* title.frame = 'group';
	*
	* var v = title.frame;
	* // returns 'group'
	*/
	frame: ReferenceFrame;

	/**
	* Maximum allowed length (in pixels) of title and subtitle text.
	*
	* @example
	* var title = new Title();
	*
	* title.limit = 100;
	*
	* var v = title.limit;
	* // returns 100
	*/
	limit?: number;

	/**
	* Line height for multi-line title text.
	*
	* @example
	* var title = new Title();
	*
	* title.lineHeight = 2;
	*
	* var v = title.lineHeight;
	* // returns 2
	*/
	lineHeight?: number;

	/**
	* Orthogonal offset (in pixels) by which to displace the title from its position along the edge of the chart.
	*
	* @example
	* var title = new Title();
	*
	* title.offset = 12;
	*
	* var v = title.offset;
	* // returns 12
	*/
	offset?: number;

	/**
	* Title orientation.
	*
	* @example
	* var title = new Title();
	*
	* title.orient = 'bottom';
	*
	* var v = title.orient;
	* // returns 'bottom'
	*/
	orient: Orientation;

	/**
	* Subtitle text.
	*
	* @example
	* var title = new Title();
	*
	* title.subtitle = 'foo bar';
	*
	* var v = title.subtitle;
	* // returns [ 'foo bar' ]
	*/
	subtitle?: Array<string>;

	/**
	* Color of the subtitle text.
	*
	* @example
	* var title = new Title();
	*
	* title.subtitleColor = 'steelblue';
	*
	* var v = title.subtitleColor;
	* // returns 'steelblue'
	*/
	subtitleColor?: string;

	/**
	* Font name for the subtitle text.
	*
	* @example
	* var title = new Title();
	*
	* title.subtitleFont = 'Arial';
	*
	* var v = title.subtitleFont;
	* // returns 'Arial'
	*/
	subtitleFont?: string;

	/**
	* Font size for the subtitle text.
	*
	* @example
	* var title = new Title();
	*
	* title.subtitleFontSize = 14;
	*
	* var v = title.subtitleFontSize;
	* // returns 14
	*/
	subtitleFontSize?: number;

	/**
	* Font style for the subtitle text.
	*
	* @example
	* var title = new Title();
	*
	* title.subtitleFontStyle = 'italic';
	*
	* var v = title.subtitleFontStyle;
	* // returns 'italic'
	*/
	subtitleFontStyle?: string;

	/**
	* Font weight for the subtitle text.
	*
	* @example
	* var title = new Title();
	*
	* title.subtitleFontWeight = 'bold';
	*
	* var v = title.subtitleFontWeight;
	* // returns 'bold'
	*/
	subtitleFontWeight?: string | number;

	/**
	* Line height for multi-line subtitle text.
	*
	* @example
	* var title = new Title();
	*
	* title.subtitleLineHeight = 16;
	*
	* var v = title.subtitleLineHeight;
	* // returns 16
	*/
	subtitleLineHeight?: number;

	/**
	* Padding (in pixels) between title and subtitle text.
	*
	* @example
	* var title = new Title();
	*
	* title.subtitlePadding = 24;
	*
	* var v = title.subtitlePadding;
	* // returns 24
	*/
	subtitlePadding?: number;

	/**
	* Title text.
	*
	* @example
	* var title = new Title();
	*
	* title.text = 'Beep boop';
	*
	* var v = title.text;
	* // returns [ 'Beep boop' ]
	*/
	text: Array<string>;

	/**
	* Integer z-index indicating the layering of the title group relative to other axis, mark, and legend groups.
	*
	* @example
	* var title = new Title();
	*
	* title.zindex = 2;
	*
	* var v = title.zindex;
	* // returns 2
	*/
	zindex: number;

	/**
	* List of enumerable properties.
	*
	* @example
	* var title = new Title();
	*
	* var v = title.properties;
	* // returns [ 'aria', 'align', 'anchor', 'angle', 'baseline', 'color', 'dx', 'dy', 'encode', 'font', 'fontSize', 'fontStyle', 'fontWeight', 'frame', 'limit', 'lineHeight', 'offset', 'orient', 'subtitle', 'subtitleColor', 'subtitleFont', 'subtitleFontSize', 'subtitleFontStyle', 'subtitleFontWeight', 'subtitleLineHeight', 'subtitlePadding', 'text', 'zindex' ]
	*/
	readonly properties: Array<string>;

	/**
	* Serializes a title instance to a JSON object.
	*
	* ## Notes
	*
	* -   This method is implicitly invoked by `JSON.stringify`.
	*
	* @returns JSON object
	*
	* @example
	* var title = new Title({
	*     'text': 'Beep boop'
	* });
	*
	* var v = title.toJSON();
	* // returns { 'aria': true, 'anchor': 'middle', 'frame': 'bounds', 'orient': 'top', 'text': [ 'Beep boop' ], 'zindex': 0 }
	*/
	toJSON(): JSON;
}

/**
* Interface defining a title constructor which is both "newable" and "callable".
*/
interface Constructor {
	/**
	* Title constructor.
	*
	* @param options - constructor options
	* @param options.align - horizontal text alignment of the title and subtitle
	* @param options.anchor - anchor position for placing the title and subtitle (default: 'middle')
	* @param options.angle - angle (in degrees) of the title and subtitle text
	* @param options.aria - boolean indicating whether ARIA attributes should be included in SVG output (default: true)
	* @param options.baseline - vertical baseline of the title and subtitle text
	* @param options.color - color of the title text
	* @param options.dx - horizontal offset (in pixels) added to the title and subtitle x-coordinate
	* @param options.dy - vertical offset (in pixels) added to the title and subtitle y-coordinate
	* @param options.encode - mark encodings for custom title styling
	* @param options.font - font name of the title text
	* @param options.fontSize - font size of the title text
	* @param options.fontStyle - font style of the title text
	* @param options.fontWeight - font weight of the title text
	* @param options.frame - reference frame for the anchor position (default: 'bounds')
	* @param options.limit - maximum allowed length (in pixels) of title and subtitle text
	* @param options.lineHeight - line height for multi-line title text
	* @param options.offset - orthogonal offset (in pixels) by which to displace the title from its position along the edge of the chart
	* @param options.orient - title orientation (default: 'top')
	* @param options.subtitle - subtitle text
	* @param options.subtitleColor - color of the subtitle text
	* @param options.subtitleFont - font name for the subtitle text
	* @param options.subtitleFontSize - font size for the subtitle text
	* @param options.subtitleFontStyle - font style for the subtitle text
	* @param options.subtitleFontWeight - font weight for the subtitle text
	* @param options.subtitleLineHeight - line height for multi-line subtitle text
	* @param options.subtitlePadding - padding (in pixels) between title and subtitle text
	* @param options.text - title text (default: [])
	* @param options.zindex - integer z-index indicating the layering of the title group relative to other axis, mark, and legend groups (default: 0)
	* @throws options argument must be an object
	* @throws must provide valid options
	* @returns title instance
	*
	* @example
	* var title = new Title({
	*     'text': 'Beep boop'
	* });
	*
	* var v = title.text;
	* // returns [ 'Beep boop' ]
	*/
	new ( options?: Options ): Title;

	/**
	* Title constructor.
	*
	* @param options - constructor options
	* @param options.align - horizontal text alignment of the title and subtitle
	* @param options.anchor - anchor position for placing the title and subtitle (default: 'middle')
	* @param options.angle - angle (in degrees) of the title and subtitle text
	* @param options.aria - boolean indicating whether ARIA attributes should be included in SVG output (default: true)
	* @param options.baseline - vertical baseline of the title and subtitle text
	* @param options.color - color of the title text
	* @param options.dx - horizontal offset (in pixels) added to the title and subtitle x-coordinate
	* @param options.dy - vertical offset (in pixels) added to the title and subtitle y-coordinate
	* @param options.encode - mark encodings for custom title styling
	* @param options.font - font name of the title text
	* @param options.fontSize - font size of the title text
	* @param options.fontStyle - font style of the title text
	* @param options.fontWeight - font weight of the title text
	* @param options.frame - reference frame for the anchor position (default: 'bounds')
	* @param options.limit - maximum allowed length (in pixels) of title and subtitle text
	* @param options.lineHeight - line height for multi-line title text
	* @param options.offset - orthogonal offset (in pixels) by which to displace the title from its position along the edge of the chart
	* @param options.orient - title orientation (default: 'top')
	* @param options.subtitle - subtitle text
	* @param options.subtitleColor - color of the subtitle text
	* @param options.subtitleFont - font name for the subtitle text
	* @param options.subtitleFontSize - font size for the subtitle text
	* @param options.subtitleFontStyle - font style for the subtitle text
	* @param options.subtitleFontWeight - font weight for the subtitle text
	* @param options.subtitleLineHeight - line height for multi-line subtitle text
	* @param options.subtitlePadding - padding (in pixels) between title and subtitle text
	* @param options.text - title text (default: [])
	* @param options.zindex - integer z-index indicating the layering of the title group relative to other axis, mark, and legend groups (default: 0)
	* @throws options argument must be an object
	* @throws must provide valid options
	* @returns title instance
	*
	* @example
	* var title = Title({
	*     'text': 'Beep boop'
	* });
	*
	* var v = title.text;
	* // returns [ 'Beep boop' ]
	*/
	( options?: Options ): Title;
}

/**
* Title constructor.
*
* @param options - constructor options
* @param options.align - horizontal text alignment of the title and subtitle
* @param options.anchor - anchor position for placing the title and subtitle (default: 'middle')
* @param options.angle - angle (in degrees) of the title and subtitle text
* @param options.aria - boolean indicating whether ARIA attributes should be included in SVG output (default: true)
* @param options.baseline - vertical baseline of the title and subtitle text
* @param options.color - color of the title text
* @param options.dx - horizontal offset (in pixels) added to the title and subtitle x-coordinate
* @param options.dy - vertical offset (in pixels) added to the title and subtitle y-coordinate
* @param options.encode - mark encodings for custom title styling
* @param options.font - font name of the title text
* @param options.fontSize - font size of the title text
* @param options.fontStyle - font style of the title text
* @param options.fontWeight - font weight of the title text
* @param options.frame - reference frame for the anchor position (default: 'bounds')
* @param options.limit - maximum allowed length (in pixels) of title and subtitle text
* @param options.lineHeight - line height for multi-line title text
* @param options.offset - orthogonal offset (in pixels) by which to displace the title from its position along the edge of the chart
* @param options.orient - title orientation (default: 'top')
* @param options.subtitle - subtitle text
* @param options.subtitleColor - color of the subtitle text
* @param options.subtitleFont - font name for the subtitle text
* @param options.subtitleFontSize - font size for the subtitle text
* @param options.subtitleFontStyle - font style for the subtitle text
* @param options.subtitleFontWeight - font weight for the subtitle text
* @param options.subtitleLineHeight - line height for multi-line subtitle text
* @param options.subtitlePadding - padding (in pixels) between title and subtitle text
* @param options.text - title text (default: [])
* @param options.zindex - integer z-index indicating the layering of the title group relative to other axis, mark, and legend groups (default: 0)
* @throws options argument must be an object
* @throws must provide valid options
* @returns title instance
*
* @example
* var title = new Title();
* // returns <Title>
*
* var v = title.toJSON();
* // returns { 'aria': true, 'anchor': 'middle', 'frame': 'bounds', 'orient': 'top', 'text': [], 'zindex': 0 }
*/
declare var ctor: Constructor;


// EXPORTS //

export = ctor;

// eslint-doctest-alias: Title
